<script setup>
import {computed,reactive,ref,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import {state,validateField} from '../store'
const route=useRoute(),router=useRouter(),signup=computed(()=>route.path==='/dang-ky'),otp=computed(()=>route.path==='/xac-thuc'),role=ref('student'),form=reactive({name:'',email:'',phone:'',password:'',confirm:'',terms:false,code:''}),errors=reactive({}),info=ref(''),visible=ref(false),pending=ref(null),expires=ref(Date.now()+120000),now=ref(Date.now()),attempts=ref(0)
const interval=setInterval(()=>now.value=Date.now(),1000);onUnmounted(()=>clearInterval(interval))
const seconds=computed(()=>Math.max(0,Math.ceil((expires.value-now.value)/1000)))
watch(()=>route.path,()=>{Object.keys(errors).forEach(k=>delete errors[k]);info.value=''})
function finish(){if(pending.value)Object.assign(state.profile,{name:pending.value.name,email:pending.value.email,phone:form.phone});state.user={name:pending.value?.name||state.profile.name,email:pending.value?.email||form.email,role:role.value};router.push(typeof route.query.redirect==='string'&&route.query.redirect.startsWith('/')?route.query.redirect:'/ho-so')}
function submit(){Object.keys(errors).forEach(k=>delete errors[k]);if(otp.value){if(!seconds.value)errors.code='Mã đã hết hạn. Hãy gửi lại.';else if(attempts.value>=5)errors.code='Đã sai 5 lần. Hãy gửi lại mã.';else if(form.code!=='246810'){attempts.value++;errors.code='Mã demo không đúng. Dùng mã 246810.'}else finish();return}
for(const key of signup.value?['name','email','phone']:['email']){const e=validateField(key,form[key]);if(e)errors[key]=e}
if(form.password.length<8)errors.password='Mật khẩu cần ít nhất 8 ký tự.'
if(signup.value&&form.password!==form.confirm)errors.confirm='Mật khẩu xác nhận chưa khớp.'
if(signup.value&&!form.terms)errors.terms='Bạn cần đồng ý điều khoản để tiếp tục.'
if(Object.keys(errors).length)return
if(signup.value){pending.value={name:form.name,email:form.email};expires.value=Date.now()+120000;router.push({path:'/xac-thuc',query:route.query})}else finish()
}
function resend(){expires.value=Date.now()+120000;attempts.value=0;form.code='';delete errors.code;info.value='Đã tạo lại mã demo: 246810. Không gửi email hoặc SMS.'}
</script>
<template><div class="container auth-page"><div class="auth-illustration"><span class="eyebrow">FindMyRoom · Cần Thơ</span><h1>Một chỗ ở mới.<br>Một khởi đầu mới.</h1><img src="/illustrations/friends.svg" alt="Những người bạn cùng xây dựng không gian sống"><p>Tìm trọ dễ hơn.<br>Tìm bạn ở cùng hợp hơn.</p></div><section class="auth-card"><span class="eyebrow">Chào bạn,</span><h2>{{otp?'Xác thực tài khoản':signup?'Tạo tài khoản mới':'Chào mừng bạn trở lại'}}</h2><p class="muted">{{otp?'Nhập mã 6 chữ số để hoàn tất đăng ký.':signup?'Bắt đầu hành trình tìm chỗ ở của bạn.':'Đăng nhập để tiếp tục hành trình tìm trọ.'}}</p><p class="demo-label"><Icon name="info" :size="16"/>Bản demo · {{otp?'Mã xác thực: 246810':'Không tạo tài khoản hay xác thực thật'}}</p><div class="segmented" v-if="!otp"><button @click="role='student'" :class="{active:role==='student'}">Sinh viên</button><button @click="role='landlord'" :class="{active:role==='landlord'}">Chủ trọ</button></div><form @submit.prevent="submit" novalidate><template v-if="!otp"><label v-if="signup" class="field"><span>Họ và tên *</span><input v-model.trim="form.name" aria-label="Họ và tên *" autocomplete="name" placeholder="Nhập họ và tên" :aria-invalid="!!errors.name"><small class="error" v-if="errors.name">{{errors.name}}</small></label><label class="field"><span>Email *</span><input v-model.trim="form.email" aria-label="Email *" type="email" autocomplete="email" placeholder="ban@student.ctu.edu.vn" :aria-invalid="!!errors.email"><small class="error" v-if="errors.email">{{errors.email}}</small></label><label v-if="signup" class="field"><span>Số điện thoại *</span><input v-model.trim="form.phone" aria-label="Số điện thoại *" type="tel" autocomplete="tel" placeholder="09xx xxx xxx" :aria-invalid="!!errors.phone"><small class="error" v-if="errors.phone">{{errors.phone}}</small></label><label class="field"><span>Mật khẩu *</span><div class="password-input"><input v-model="form.password" aria-label="Mật khẩu *" :type="visible?'text':'password'" :autocomplete="signup?'new-password':'current-password'" placeholder="Ít nhất 8 ký tự" :aria-invalid="!!errors.password"><button type="button" class="icon-button" @click="visible=!visible" :aria-label="visible?'Ẩn mật khẩu':'Hiện mật khẩu'"><Icon name="eye" :size="18"/></button></div><small class="error" v-if="errors.password">{{errors.password}}</small></label><label v-if="signup" class="field"><span>Xác nhận mật khẩu *</span><input v-model="form.confirm" aria-label="Xác nhận mật khẩu *" type="password" autocomplete="new-password" placeholder="Nhập lại mật khẩu" :aria-invalid="!!errors.confirm"><small class="error" v-if="errors.confirm">{{errors.confirm}}</small></label><label v-if="signup" class="check"><input type="checkbox" v-model="form.terms">Tôi đồng ý với điều khoản dịch vụ và chính sách bảo mật.</label><div v-else class="auth-options"><span class="muted">Phiên đăng nhập được giữ trong tab này</span><button type="button" class="text-button" @click="info='Đây là bản demo. Nhập email hợp lệ và mật khẩu bất kỳ từ 8 ký tự để trải nghiệm.'">Quên mật khẩu?</button></div><small class="error" v-if="errors.terms">{{errors.terms}}</small></template><label v-else class="field"><span>Mã xác thực *</span><input v-model="form.code" aria-label="Mã xác thực *" class="otp-input" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="000000" :aria-invalid="!!errors.code"><small class="error" v-if="errors.code">{{errors.code}}</small><span class="muted">Mã hết hạn sau {{seconds}} giây</span></label><button class="button primary full" type="submit">{{otp?'Xác nhận':signup?'Đăng ký':'Đăng nhập'}} <Icon name="arrow" :size="18"/></button></form><button v-if="otp" class="text-button resend" @click="resend">Gửi lại mã demo</button><template v-else><div class="divider"><span>Hoặc</span></div><div class="social-buttons"><button class="button secondary" @click="info='Google OAuth chưa được kết nối. Hãy dùng form demo phía trên.'"><strong>G</strong> Google</button><button class="button secondary" @click="info='Facebook OAuth chưa được kết nối. Hãy dùng form demo phía trên.'"><strong>f</strong> Facebook</button></div><p class="center auth-switch">{{signup?'Đã có tài khoản?':'Chưa có tài khoản?'}} <RouterLink :to="{path:signup?'/dang-nhap':'/dang-ky',query:route.query}">{{signup?'Đăng nhập ngay':'Đăng ký ngay'}}</RouterLink></p></template><p v-if="info" class="notice" role="status">{{info}}</p></section></div></template>
